const listInvoices = `-- name: ListInvoices :many
SELECT i.id, i.uuid, i.number, i.profile, i.invoice_type, i.status, i.issue_date, i.currency, i.receiver_type,
    i.receiver_name, i.receiver_identity_hint, i.receiver_einvoice, i.line_extension_amount, i.tax_amount,
    i.payable_amount, i.linked_amount, i.external_ref, i.hold_reason, i.last_error, i.returned_at, i.cancelled_at,
    i.validation_errors, i.created_at, i.updated_at,
    b.uuid AS branch_uuid, b.code AS branch_code, b.name AS branch_name,
    a.uuid AS account_uuid, a.code AS account_code, a.name AS account_name,
    r.uuid AS rental_uuid, r.reference AS rental_reference,
    ri.uuid AS returns_uuid, ri.number AS returns_number,
    j.uuid AS job_uuid, j.status AS job_status, j.attempts AS job_attempts,
    COUNT(*) OVER ()::bigint AS total
FROM invoices i
JOIN branches b ON b.organization_id = i.organization_id AND b.id = i.branch_id
LEFT JOIN accounts a ON a.organization_id = i.organization_id AND a.id = i.account_id
LEFT JOIN rentals r ON r.organization_id = i.organization_id AND r.id = i.rental_id
LEFT JOIN invoices ri ON ri.organization_id = i.organization_id AND ri.id = i.returns_invoice_id
LEFT JOIN integration_jobs j ON j.organization_id = i.organization_id AND j.id = i.integration_job_id
WHERE i.organization_id = $1
  AND b.organization_id = $1
  AND (a.id IS NULL OR a.organization_id = $1)
  AND (r.id IS NULL OR r.organization_id = $1)
  AND (ri.id IS NULL OR ri.organization_id = $1)
  AND (j.id IS NULL OR j.organization_id = $1)
  AND ($2::bigint[] IS NULL OR i.branch_id = ANY($2::bigint[]))
  AND ($3::bigint[] IS NULL OR i.branch_id = ANY($3::bigint[]))
  AND ($4::text[] IS NULL OR i.status = ANY($4::text[]))
  AND ($5::text[] IS NULL OR i.profile = ANY($5::text[]))
  AND ($6::text[] IS NULL OR i.invoice_type = ANY($6::text[]))
  AND ($7::bigint IS NULL OR i.account_id = $7::bigint)
  AND ($8::bigint IS NULL OR i.rental_id = $8::bigint OR EXISTS (
      SELECT 1 FROM ledger_entry_links lk
      JOIN ledger_entries le ON le.organization_id = lk.organization_id AND le.id = lk.entry_id
      WHERE lk.organization_id = i.organization_id AND le.organization_id = i.organization_id
        AND lk.invoice_id = i.id AND le.rental_id = $8::bigint
  ))
  AND ($9::date IS NULL OR i.issue_date >= $9::date)
  AND ($10::date IS NULL OR i.issue_date <= $10::date)
  AND ($11::boolean IS NULL OR (
      $11::boolean = (i.status = 'failed' OR j.status IN ('needs_verification', 'waiting_dependency', 'blocked'))
  ))
  AND ($12::text IS NULL
       OR i.number ILIKE '%' || $12::text || '%'
       OR i.receiver_name ILIKE '%' || $12::text || '%'
       OR r.reference ILIKE '%' || $12::text || '%'
       OR a.name ILIKE '%' || $12::text || '%')
ORDER BY
    CASE WHEN $13::text = 'issue_date' AND NOT $14::boolean THEN i.issue_date END ASC,
    CASE WHEN $13::text = 'issue_date' AND $14::boolean THEN i.issue_date END DESC,
    CASE WHEN $13::text = 'number' AND NOT $14::boolean THEN i.number END ASC,
    CASE WHEN $13::text = 'number' AND $14::boolean THEN i.number END DESC,
    CASE WHEN $13::text = 'payable_amount' AND NOT $14::boolean THEN i.payable_amount END ASC,
    CASE WHEN $13::text = 'payable_amount' AND $14::boolean THEN i.payable_amount END DESC,
    CASE WHEN $13::text = 'created_at' AND NOT $14::boolean THEN i.created_at END ASC,
    i.created_at DESC, i.id DESC
LIMIT $16 OFFSET $15
`

